def decide_refresh_action(*, hash_matches, token_revoked, token_expired):
    """Return the refresh-token action according to validation and reuse policy."""
    if not hash_matches:
        return "reject_invalid"
    if token_revoked:
        return "revoke_family"
    if token_expired:
        return "reject_expired"
    return "rotate"

